create function public.dashboard() returns jsonb language sql stable security invoker set search_path='' as $$select jsonb_build_object('total',count(*),'confirmed',count(*) filter(where status='confirmed'),'shipped',count(*) filter(where status='shipped'),'delivered',count(*) filter(where status='delivered'),'overdue',(select coalesce(jsonb_agg(t),'[]'::jsonb) from(select o.id,o.name,o.code,o.status from public.orders o join public.settings s using(workspace_id) where ((o.status='confirmed' and o.confirmed_at<now()-make_interval(days=>s.confirm_days)) or(o.status='shipped' and o.shipped_at<now()-make_interval(days=>s.ship_days))) order by o.created_at limit 8)t),'alerts',(select coalesce(jsonb_agg(n),'[]'::jsonb) from(select id,title,body,created_at from public.notifications order by created_at desc limit 5)n)) from public.orders$$;
revoke all on function public.dashboard() from public,anon;
grant execute on function public.dashboard() to authenticated;
